import numpy as np

def feature(item, bins, capacity):
    """For small jobs only: negative of the bin's tighter residual fraction, so nearly-full-in-one-resource bins score highest."""
    small = (item < 0.2 * capacity).all()
    if not small:
        return np.zeros(bins.shape[0])
    r = np.clip(bins - item, 0, None)
    frac = r / capacity
    return -np.minimum(frac[:, 0], frac[:, 1])
```

Active only when both resources of the item are below 20% of capacity, returning 0 otherwise; the new empty bin naturally gets the most negative value (least preferred).
